class Solution:
    def merge(self, intervals: List[List[int]]) -> List[List[int]]:
        intervals.sort(key=lambda x: x[0])
        res = []
        l, r = intervals[0][0], intervals[0][1]
        for i in range(1, len(intervals)):
            if intervals[i][0] > r:
                # 无法合并, 更新为新区间
                res.append([l, r])
                l, r = intervals[i][0], intervals[i][1]
            else:
                # 可以合并, 更新右端点
                r = max(r, intervals[i][1])
        if [l,r] not in res:
            res.append([l,r])
        return res
